var inversions = 0;
void mergeSort(int l, int r) {
  final m = (l + r) ~/ 2;
  mergeSort(l, m);
  mergeSort(m + 1, r);
  var i = l, j = m + 1;
  while (i <= m && j <= r) {
    if (a[i] < a[j]) {
      temp.add(a[i++]);
    } else {
      inversions += m - i + 1;
      temp.add(a[j++]);
    }
  }
  print('merge [$l..$r]: ${temp.join(' ')}');
